// Decides what a caller does after its LLM call failed. A 429 is asked again once, with a
// one-token request: while a limit is hit the provider refuses it (no tokens spent) and its body
// names the limit (per minute or per day), its size and when it clears.
//   retry: a per-minute limit. Waits here, then the caller sends the same item again.
//   stop:  a per-day limit. The caller stops: the email is held back, not failed.
//   other: not a rate limit, or still limited after 6 waits. The caller decides.
const input = $('When Called by Another Workflow').first().json;
const err = String(input.error || 'LLM request failed');
const { error, ...item } = input.item || {};
const res = $input.first().json;
const out = (rate_limit) => [{ json: { ...item, rate_limit: { ...rate_limit, model: input.model, probe_status: res.statusCode ?? null } } }];
if (!err.includes('too many requests')) return out({ action: 'other', message: err });
let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = {}; } }
const msg = String((body && body.error && body.error.message) || '');
const kind = (msg.match(/\((TPM|TPD|RPM|RPD)\)/) || [])[1] || '';
// "try again in 1h2m3.5s" / "7.5s" / "157.5ms" -> seconds
let delay = NaN;
const t = msg.match(/try again in ([0-9hm.]+m?s)/);
if (t) {
  const p = t[1].match(/^(?:(\d+)h)?(?:(\d+)m(?!s))?(?:([\d.]+)s)?(?:([\d.]+)ms)?$/);
  if (p) delay = (+p[1] || 0) * 3600 + (+p[2] || 0) * 60 + (+p[3] || 0) + (+p[4] || 0) / 1000;
}
const headers = res.headers || {};
if (!Number.isFinite(delay) && headers['retry-after']) delay = Number(headers['retry-after']);
if (/D$/.test(kind) || /per day/i.test(msg)) {
  const resetsAt = new Date(Date.now() + (Number.isFinite(delay) ? delay : 3600) * 1000).toISOString();
  return out({ action: 'stop', limit: kind === 'RPD' ? 'requests per day' : 'tokens per day',
    quota_limit: Number((msg.match(/Limit (\d+)/) || [])[1]) || null, resets_at: resetsAt, message: err });
}
if (Number(input.attempt) >= 6) return out({ action: 'other', message: err + ' (still limited after 6 waits)' });
// A repeat that went through means the minute has just cleared.
const wait = res.statusCode === 429 ? Math.min(Number.isFinite(delay) ? delay : 20, 60) + 1 : 2;
return out({ action: 'retry', limit: kind === 'RPM' ? 'requests per minute' : 'tokens per minute', wait_s: Math.ceil(wait) });
